CREATE TABLE accounts(id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspaces(id text PRIMARY KEY, account_id text NOT NULL REFERENCES accounts, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO accounts(id) VALUES ('owner');
INSERT INTO workspaces(id,account_id,name) VALUES ('personal','owner','Personal workspace');
CREATE TABLE sessions(token_hash text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces, expires_at timestamptz NOT NULL);
CREATE TABLE projects(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces,name text NOT NULL,repository text NOT NULL,paused boolean NOT NULL DEFAULT false,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id),UNIQUE(workspace_id,repository));
CREATE TABLE devices(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces,name text NOT NULL,platform text NOT NULL,token_hash text UNIQUE,revoked boolean NOT NULL DEFAULT false,last_contact timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id));
CREATE TABLE device_projects(workspace_id text NOT NULL,device_id text NOT NULL,project_id text NOT NULL,PRIMARY KEY(device_id,project_id),FOREIGN KEY(workspace_id,device_id) REFERENCES devices(workspace_id,id),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE pairings(code_hash text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces,name text NOT NULL,project_ids jsonb NOT NULL, expires_at timestamptz NOT NULL,device_id text REFERENCES devices);
CREATE TABLE events(seq bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces,project_id text,kind text NOT NULL,subject_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE INDEX events_owner_cursor ON events(workspace_id,seq);
CREATE TABLE decisions(id text PRIMARY KEY,workspace_id text NOT NULL,project_id text NOT NULL,subject_version bigint NOT NULL,question text NOT NULL,answer text,version bigint NOT NULL DEFAULT 1,request_id text,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '1 day',FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), UNIQUE(project_id,subject_version),UNIQUE(workspace_id,request_id));
CREATE TABLE manager_messages(id text PRIMARY KEY,workspace_id text NOT NULL,project_id text NOT NULL,body text NOT NULL,request_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), UNIQUE(workspace_id,request_id));
CREATE TABLE attempt_reports(id text NOT NULL,workspace_id text NOT NULL,project_id text NOT NULL,device_id text NOT NULL,issue_number integer NOT NULL,base_sha text NOT NULL,candidate_sha text NOT NULL,phase text NOT NULL,state text NOT NULL,version bigint NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id), FOREIGN KEY(device_id,project_id) REFERENCES device_projects(device_id,project_id),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
